/**
 * DYNAMIC VISUALIZER EMBED — V5 (owner go-ahead 2026-08-23).
 *
 * Mounts the shared viz panel (calcv2/viz/layer3/panel.mjs — the SAME
 * renderer the bench runs) into the page's centre-band reservation and
 * feeds it ONE-WAY from the page's state. Nothing here writes page
 * state, reads back into any computation, or is scraped by any other
 * module — the visualizer's output type is pixels, full stop
 * (feedsNumbers: false; M9).
 *
 * PAYLOAD SOURCES:
 *  - PRESETS: baked fixture payloads (generated by the sealed node
 *    runner), scaled client-side to the inherited ship length (pure
 *    geometry algebra — the scaleGeometryRecord precedent). ⚠ Whether
 *    presets stay pre-baked (presetDynamics precedent) or move to
 *    in-browser generation awaits the owner's amendment call on the
 *    sealed "baked JSON = fixtures only" rule.
 *  - UPLOADS (V5 step 2): generated IN-BROWSER by the payload worker
 *    (calcv2/viz/payload-worker.mjs) from the SAME canonical hull the
 *    page's shape worker measured (upload-hull rule: one hull, every
 *    consumer). Generation is seconds-heavy — the reservation note
 *    shows MEASURING while it runs; stale completions are discarded by
 *    sequence (the page's own runId pattern).
 *
 * ORIENTATION: pitch/yaw presses are REAL regenerate-on-snap (round-2
 * F3): presets swap to the baked 24-group variant; uploads re-run the
 * generator with the composed rotation. Sunship exempt (authored).
 */
import { createVizPanel } from '/calcv2/viz/layer3/panel.mjs?v=dev1';

const FIXTURES = '/calcv2/viz/fixtures/';
const PRESET_KEYS = new Set(['sunship', 'cigar', 'bottle', 'car', 'washingmachine', 'aerosmena']);
const UPLOAD_AXIS = '+Z';                // §4.1 ratified default for uploads
const GEN_LENGTH_FALLBACK = 300;         // generate at 300 m when no ship length exists yet

const cache = new Map();
async function fetchJson(url) {
  if (!cache.has(url)) {
    cache.set(url, fetch(url).then((r) => (r.ok ? r.json() : null)).catch(() => null));
  }
  return cache.get(url);
}

/* ---- pure length scaling (k = target / built length) ------------------ */
const mulArr = (a, k) => a.map((v) => v * k);
function scaleState(st, k) {
  if (!st) return st;
  return {
    ...st,
    extentM: { x0M: st.extentM.x0M * k, x1M: st.extentM.x1M * k, lengthM: st.extentM.lengthM * k },
    maxRadiusM: st.maxRadiusM * k,
    railsRM: mulArr(st.railsRM, k),
    silhouettes: {
      ...st.silhouettes,
      xGrid: { ...st.silhouettes.xGrid, x0M: st.silhouettes.xGrid.x0M * k, dxM: st.silhouettes.xGrid.dxM * k },
      yHiM: mulArr(st.silhouettes.yHiM, k), yLoM: mulArr(st.silhouettes.yLoM, k),
      zHiM: mulArr(st.silhouettes.zHiM, k), zLoM: mulArr(st.silhouettes.zLoM, k),
    },
    frontalContourRM: mulArr(st.frontalContourRM, k),
    // tangentRad / tangentDomain / scalar / eligibility: scale-invariant
  };
}
function scaleRenderPayload(p, k) {
  if (Math.abs(k - 1) < 1e-9) return p;
  return {
    ...p,
    payloadId: `${p.payloadId}@x${k.toFixed(6)}`,     // distinct id → engine state reset rule fires
    frame: { ...p.frame, frontalAreaM2: p.frame.frontalAreaM2 * k * k },
    retracted: scaleState(p.retracted, k),
    extended: scaleState(p.extended, k),
    spheres: {
      sphere1: p.spheres.sphere1 && { centerM: mulArr(p.spheres.sphere1.centerM, k), radiusM: p.spheres.sphere1.radiusM * k },
      sphere2: p.spheres.sphere2 && { centerM: mulArr(p.spheres.sphere2.centerM, k), radiusM: p.spheres.sphere2.radiusM * k },
    },
    worldBounds: {
      ...p.worldBounds,
      xMinM: p.worldBounds.xMinM * k, xMaxM: p.worldBounds.xMaxM * k,
      yAbsM: p.worldBounds.yAbsM * k, zAbsM: p.worldBounds.zAbsM * k,
    },
    linework: p.linework && {
      ...p.linework,
      segsM: p.linework.segsM && mulArr(p.linework.segsM, k),
      pointsM: p.linework.pointsM && mulArr(p.linework.pointsM, k),
    },
  };
}

/* ---- the 24-rotation group walk (matches the runner's generators) ----- */
const ROT_I = [1, 0, 0, 0, 1, 0, 0, 0, 1];
const ROT_P = [0, -1, 0, 1, 0, 0, 0, 0, 1];
const ROT_Y = [0, 0, 1, 0, 1, 0, -1, 0, 0];
const rotCompose = (A, B) => {
  const C = new Array(9);
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
    C[r * 3 + c] = A[r * 3] * B[c] + A[r * 3 + 1] * B[3 + c] + A[r * 3 + 2] * B[6 + c];
  }
  return C;
};

export function mountDynamicViz(container, placeholderNote) {
  let panel = null;
  let ident = null;                      // 'preset:<key>' | 'upload#<revision>' | null
  let currentKey = null;                 // preset fixture key (null in upload mode)
  let currentFile = null;                // fixture file in force (default or orientation variant)
  let uploadGeo = null;                  // the published vizGeo for the active upload
  let uploadName = '';
  let orientM = ROT_I;
  let wantTail = false;                  // E+A+S unlock: generic-tail visuals in force
  let lastLenM = null;
  let lenTimer = null;
  let pendingLenM = null;
  let manifest = null;
  let genWorker = null;
  let genSeq = 0;

  const note = (text) => {
    if (!placeholderNote) return;
    if (text == null) { placeholderNote.style.display = 'none'; return; }
    placeholderNote.style.display = '';
    placeholderNote.textContent = text;
  };

  /* M7 PHONE PORTRAIT (ruling 2026-08-18, enacted 2026-08-24): portrait
     phones read the instrument as PLAN view with the flow running
     top→bottom — the 2.6 rectangle turned tall. The breakpoint matches
     mobile.js's PHONE (768px). Rotating back restores the desktop
     default (side view, L→R); the in-rectangle buttons still override
     within either mode. Layout only — the engine never sees any of it. */
  const m7Portrait = window.matchMedia('(max-width: 768px) and (orientation: portrait)');
  function applyM7Mode() {
    if (!panel) return;
    if (m7Portrait.matches) { panel.setFlowAxis('TB'); panel.setView('plan'); }
    else { panel.setFlowAxis('LR'); panel.setView('elevation'); }
  }
  m7Portrait.addEventListener?.('change', applyM7Mode);

  function ensurePanel() {
    if (panel) return panel;
    window.__dynViz = { panel: () => panel };   // engineer debug handle (hidden panes suspend rAF — known trap)
    panel = createVizPanel({
      container,
      onOrientate: (which) => {
        const G = which === 'pitch' ? ROT_P : ROT_Y;
        if (currentKey && currentKey !== 'sunship' && manifest) {
          orientM = rotCompose(G, orientM);
          refreshPreset();
        } else if (uploadGeo) {
          orientM = rotCompose(G, orientM);
          generateUpload();                // real regenerate-on-snap for uploads
        }
      },
    });
    applyM7Mode();                 // panel may be born into a portrait phone
    return panel;
  }

  function applyPayload(raw) {
    const k = lastLenM && raw.retracted ? lastLenM / raw.retracted.extentM.lengthM : 1;
    ensurePanel().setPayload(scaleRenderPayload(raw, k));
    note(null);
  }

  /* the fixture file for the current preset + orientation + tail state.
     E+A+S generic tails are baked for the DEFAULT orientation only — a
     rotated body keeps its base payload and the tail soft-fails visually
     (honest absence; the numbers never lived here anyway). */
  function presetFile() {
    if (!currentKey) return null;
    if (wantTail && currentKey !== 'sunship' && orientM.join(',') === ROT_I.join(',')) {
      return `${currentKey}.eas.render.json`;
    }
    if (orientM.join(',') === ROT_I.join(',')) return `${currentKey}.render.json`;
    return manifest?.[currentKey]?.[orientM.join(',')] ?? `${currentKey}.render.json`;
  }
  async function refreshPreset() {
    const file = presetFile();
    if (!file) return;
    const raw = await fetchJson(FIXTURES + file);
    if (raw && currentKey) { currentFile = file; applyPayload(raw); }
    else if (currentKey && file.endsWith('.eas.render.json')) {
      // no eas payload baked — fall back to the base (soft visual absence)
      const base = await fetchJson(FIXTURES + `${currentKey}.render.json`);
      if (base && currentKey) { currentFile = `${currentKey}.render.json`; applyPayload(base); }
    }
  }

  function generateUpload() {
    if (!uploadGeo) return;
    if (!genWorker) {
      genWorker = new Worker('/calcv2/viz/payload-worker.mjs?v=dev1', { type: 'module' });
      genWorker.onmessage = (e) => {
        if (e.data.seq !== genSeq) return;          // stale completion — discard (ruled pattern)
        if (e.data.error || !e.data.payload) {
          note(`VISUALIZER — COULD NOT MEASURE THIS SHAPE (${e.data.error ?? 'no payload'})`);
          return;
        }
        if (!ident?.startsWith('upload')) return;    // shape changed while measuring
        applyPayload(e.data.payload);
        ensurePanel().setOrientEnabled(true);
      };
    }
    note('VISUALIZER — MEASURING…');
    genSeq++;
    genWorker.postMessage({
      seq: genSeq,
      name: uploadName,
      hullPoints: uploadGeo.hullPoints,
      hullFaces: uploadGeo.hullFaces,
      meshSegments: uploadGeo.meshSegments,
      meshPoints: uploadGeo.meshPoints,
      centre: uploadGeo.centre,
      radius: uploadGeo.radius,
      axis: UPLOAD_AXIS,
      rot: orientM,
      lengthM: lastLenM ?? GEN_LENGTH_FALLBACK,
      tail: wantTail ? 'generic' : 'none',
    });
  }

  async function loadPreset(key) {
    currentKey = key;
    uploadGeo = null;
    orientM = ROT_I;
    if (!manifest) manifest = await fetchJson(FIXTURES + 'orientations.json');
    const raw = await fetchJson(FIXTURES + `${key}.render.json`);
    if (!raw) {
      panel?.clear();
      note('VISUALIZER — NO PAYLOAD FOR THIS SHAPE');
      currentKey = null;
      currentFile = null;
      return;
    }
    currentFile = `${key}.render.json`;
    applyPayload(raw);
    ensurePanel().setOrientEnabled(key !== 'sunship');
  }

  function loadUpload(pub) {
    currentKey = null;
    currentFile = null;
    orientM = ROT_I;
    uploadGeo = pub.vizGeo;
    uploadName = pub.name || 'upload';
    panel?.clear();
    generateUpload();
  }

  return {
    /** One-way push from the page's paint(). Returns nothing readable. */
    update({ shapeKind, shapeId, lengthM, airspeedKmh, cd, s, tailOn, bliOn, noShip }) {
      const pub = window.__v2ActiveShape;
      const key = shapeKind === 'preset' && PRESET_KEYS.has(shapeId) ? shapeId : null;
      const nextIdent = key ? `preset:${key}`
        : (pub && pub.kind === 'upload' && pub.vizGeo ? `upload#${pub.revision}` : null);
      if (nextIdent !== ident) {
        ident = nextIdent;
        if (key) loadPreset(key);
        else if (nextIdent) loadUpload(pub);
        else {
          currentKey = null; currentFile = null; uploadGeo = null;
          panel?.clear();
          note('VISUALIZER — NO MEASURABLE SHAPE');
        }
      }

      // E+A+S unlock (owner, 2026-08-23): the tail toggle can only be ON
      // for a non-Sunship shape when the engineer chord unlocked it — so
      // tailOn on a non-Sunship IS the unlock signal. Presets swap to
      // their baked generic-tail payload; uploads regenerate with the
      // rule; refusals show honest visual absence.
      const nextTail = !!tailOn && !!ident && ident !== 'preset:sunship';
      if (nextTail !== wantTail) {
        wantTail = nextTail;
        if (currentKey) refreshPreset();
        else if (uploadGeo) generateUpload();
      }

      // Inherited length drives crossing time (kinematics ruling §7.2).
      // Debounced: presets re-apply the fixture at the new scale; uploads
      // REGENERATE at the new length (measured, not scaled).
      const len = noShip ? null : lengthM;
      if (len !== lastLenM) {
        pendingLenM = len;
        if (!lenTimer) {
          lenTimer = setTimeout(async () => {
            lenTimer = null;
            lastLenM = pendingLenM;
            if (currentFile) {
              const raw = await fetchJson(FIXTURES + currentFile);
              if (raw && currentFile) applyPayload(raw);
            } else if (uploadGeo) {
              generateUpload();
            }
          }, 250);
        }
      }

      if (panel) {
        panel.setControls({
          airspeedMps: noShip ? 0 : (airspeedKmh || 0) / 3.6,   // no ship / parked → M3: engine dormant
          smartTail: !!tailOn,
          bli: !!bliOn,
          selectedCd: Number.isFinite(cd) ? cd : 0,
          selectedS: Number.isFinite(s) ? s : 0,
        });
      }
    },
  };
}
